suppressPackageStartupMessages(library(metafor))
d <- read.csv(commandArgs(trailingOnly = TRUE)[1])
r <- rma.uni(yi = d$yi, sei = d$sei, method = "REML")
pet <- regtest(r, model = "lm", predictor = "sei", ret.fit = TRUE)
cat("class fit:", class(pet$fit), "\n")
cat("names fit:", paste(names(pet$fit), collapse=", "), "\n")
cat("b class:", class(pet$fit$b), "\n")
cat("b:\n")
print(pet$fit$b)
cat("se:\n")
print(pet$fit$se)
cat("coef:\n")
print(coef(pet$fit))
